package com.cbkres.visavole.domain

/**
 * Everything the document editor has decided, decoupled from Compose so the build stays a pure,
 * JVM-testable function. Ids are generated by the caller so the builder is deterministic.
 */
internal data class DocDraft(
    val id: String,
    val docType: DocType,
    val lastIso: String?,
    val countries: Set<String>,
    val effectiveBloc: String?,
    val effectiveHolding: String?,
    val entryType: String?,
    val residenceClass: ResidenceClass,
    val residenceClassEdited: Boolean,
    val expiry: String?,
    val validFrom: String?,
)

/** The document the draft stands for: passport, stored holding, or fully custom. */
internal fun buildDocument(draft: DocDraft, initial: Document?, world: WorldData): Document {
    val id = draft.id
    // An edit must carry the supersession pointer through, or saving revives the archived doc.
    val supersededBy = initial?.supersededBy
    val exp = draft.expiry
    val vfrom = draft.validFrom
    val initHolding = initial?.kind as? DocKind.Holding
    val countries = world.countries
    return when {
        draft.docType == DocType.PASSPORT -> {
            val iso = draft.lastIso ?: draft.countries.first()
            passportDocument(iso, countries[iso]?.name, exp, vfrom, id = id)
        }
        initHolding != null && draft.countries.isEmpty() -> {
            val h = draft.effectiveHolding!!
            val label = (world.holdings[h]?.name ?: h) + draft.residenceClass.let { " · ${it.label}" }
            // Keep what the dialog cannot change (entry type) or never touched (stored class).
            val rc = if (draft.residenceClassEdited) draft.residenceClass else initial?.residenceClass
            Document(id, label, DocKind.Holding(h, initHolding.entryType), exp, vfrom, rc, supersededBy)
        }
        else -> {
            val names = draft.countries.joinToString(", ") { countries[it]?.name ?: it }.take(80)
            val typeSuffix = draft.effectiveHolding?.let { hid -> " (${world.holdings[hid]?.name ?: hid})" } ?: ""
            // The tab carries identity only once the user moves it: while it sits on the tab the
            // document opened on, the stored kind survives — a legacy "permit" opens on the Visa
            // tab, so an untouched edit must not stamp it "visa" and break trip references.
            val stored = (initial?.kind as? DocKind.Custom)?.kind
            val kind = if (stored != null && initialTabFor(stored) == draft.docType) stored else draft.docType.kind
            // Residence entry types are not editable on the tabs; an edit must not delete a stored
            // one, and visa documents keep the dialog's selection.
            val entry = when (draft.docType) {
                DocType.VISA -> draft.entryType
                DocType.RESIDENCE -> (initial?.kind as? DocKind.Custom)?.entryType
                else -> null
            }
            val rc = if (draft.docType == DocType.RESIDENCE) draft.residenceClass else null
            Document(id, "${draft.docType.label}: $names$typeSuffix", DocKind.Custom(draft.countries, draft.effectiveBloc, kind, draft.effectiveHolding, entry), exp, vfrom, rc, supersededBy)
        }
    }
}

/** The tab an edit of a stored custom kind opens on — mirrors the dialog's tab initialisation. */
private fun initialTabFor(kind: String): DocType = when (kind) {
    "visa", "permit" -> DocType.VISA
    "passport" -> DocType.PASSPORT
    else -> DocType.RESIDENCE
}
